import{_ as t,c as a,o as s,a3 as i}from"./chunks/framework.BNw1pucY.js";const u=JSON.parse('{"title":"Review and triage templates","description":"Scaffold a pull request reviewer or an issue triager, try it locally, and deploy it.","frontmatter":{"title":"Review and triage templates","description":"Scaffold a pull request reviewer or an issue triager, try it locally, and deploy it."},"headers":[],"relativePath":"templates/reviews.md","filePath":"templates/reviews.md"}'),n={name:"templates/reviews.md"};function o(r,e,d,l,p,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="review-and-triage-templates" tabindex="-1">Review and triage templates <a class="header-anchor" href="#review-and-triage-templates" aria-label="Permalink to &quot;Review and triage templates&quot;">​</a></h1><p>Each template is one model turn. A review template reads the diff and posts one comment, and the triage template comments on a ticket you already filed.</p><table tabindex="0"><thead><tr><th>Template</th><th><code>--template</code> id</th><th>What it posts</th><th>Channel</th></tr></thead><tbody><tr><td>Security reviewer</td><td><code>security-reviewer</code></td><td>One comment on exploitable bugs, such as injection, authz bypass, secret leaks, SSRF, and RCE</td><td>GitHub</td></tr><tr><td>Thermo review</td><td><code>thermo-review</code></td><td>One comment on bugs, breaking side effects, and unintended feature exposure</td><td>GitHub</td></tr><tr><td>Thermo quality review</td><td><code>thermo-quality-review</code></td><td>One comment on structure, such as missing abstractions, deep nesting, and files past 1,000 lines</td><td>GitHub</td></tr><tr><td>Triage</td><td><code>triage-linear</code>, <code>triage-jira</code>, or <code>triage</code></td><td>A <code>Triage:</code> comment, a bug priority, and a duplicate link when titles match</td><td>Linear or Jira</td></tr></tbody></table><p><code>triage</code> is short for <code>triage-linear</code>. No review template comments on style, and the quality template doesn&#39;t argue about behavior.</p><p>The <a href="./agentic-owners.html">Agentic Approver</a> template is separate. It applies an owners policy instead of posting one findings comment.</p><h2 id="scaffold" tabindex="-1">Scaffold <a class="header-anchor" href="#scaffold" aria-label="Permalink to &quot;Scaffold&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk init ./security-reviewer --template security-reviewer \\</span></span>
<span class="line"><span>  --var repos=acme/api</span></span></code></pre></div><p>Swap the folder and the <code>--template</code> id for the row you want. <code>--var repos</code> is only for <code>security-reviewer</code>. Name repositories already connected in Cursor, separated by commas, and they must share one owner. <code>init</code> writes that list to <code>bot/lib/repos.ts</code>.</p><h2 id="try-it-locally" tabindex="-1">Try it locally <a class="header-anchor" href="#try-it-locally" aria-label="Permalink to &quot;Try it locally&quot;">​</a></h2><p>Connect GitHub in Cursor for the repositories you watch (Settings or <a href="https://cursor.com/dashboard" target="_blank" rel="noreferrer">cursor.com/dashboard</a>), then sign the host in with <code>agent-sdk login</code>. The <a href="./../guides/github.html">GitHub guide</a> covers <code>cursorAccount</code>.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk dev --cursor-events --repo acme/api</span></span>
<span class="line"><span>agent-sdk github replay https://github.com/acme/api/pull/12 --dir .</span></span></code></pre></div><p>You need pull access to replay. The channel skips drafts, writes the diff to <code>pr/diff.patch</code>, and starts a turn. The model calls <code>post_findings</code> once, and that call writes the GitHub comment. Chat replies stay in the playground.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk eval</span></span></code></pre></div><p>Eval sessions skip the GitHub write. Edit <code>bot/instructions.md</code> for what counts as a finding, and edit <code>evals/review.eval.ts</code> for the smoke cases.</p><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><p>From the agent&#39;s git checkout:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk login</span></span>
<span class="line"><span>agent-sdk deploy --cursor-events-repo acme/api</span></span></code></pre></div><p>Repeat <code>--cursor-events-repo</code> for each repository, and every repository must share one owner. The deployment watches those repositories through your team&#39;s Cursor GitHub connection, and you can change the list later without a redeploy:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>agent-sdk deployment update my-agent --event-repo acme/api --event-repo acme/web</span></span></code></pre></div><h2 id="triage-a-tracker" tabindex="-1">Triage a tracker <a class="header-anchor" href="#triage-a-tracker" aria-label="Permalink to &quot;Triage a tracker&quot;">​</a></h2><p>The template runs after someone files a ticket, so keep filing them as you do now. Connect Linear or Jira under MCP in the Cursor dashboard, then run <code>agent-sdk dev</code> and open <code>/queue/issue</code> in the playground.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/triage-agent/v1/channels/queue/issue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;content-type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;identifier&quot;: &quot;ENG-142&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;title&quot;: &quot;CSV export returns 500&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;description&quot;: &quot;Export has returned 500 since this morning.&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>For create webhooks, set <code>LINEAR_WEBHOOK_SECRET</code> or <code>JIRA_WEBHOOK_SECRET</code> and point the provider at <code>/v1/channels/webhook</code> on the deployed alias. <code>record_triage</code> comments on the issue that started the session. Edit <code>bot/skills/triage-rubric.md</code> for kinds and what <code>urgent</code> means on your team. Eval sessions skip tracker writes.</p>`,23)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
